// A grid of rows x cols cells starts as all water. The cells (r, c) in
// cells are turned into land one at a time, in order. Two land cells belong
// to the same island when they are connected through land cells that share
// an edge (up, down, left, right; diagonals do not connect).
//
// After each step, record (number of islands, size of the largest island in
// cells), with (0, 0) when there is no land. Return the list of records, one
// per element of cells.
//
// A cell outside the grid (r outside 0 .. rows-1 or c outside 0 .. cols-1;
// when rows <= 0 or cols <= 0 every cell is outside) or a cell that is
// already land changes nothing, but still produces a record.
//
// Examples:
//   island_counts(3, 3, [(0, 0), (0, 1), (1, 2), (2, 1)]) == [(1, 1), (1, 2), (2, 2), (3, 2)]
//   island_counts(2, 2, [(0, 0), (1, 1), (0, 1)]) == [(1, 1), (2, 1), (1, 3)]
fn island_counts(rows: Int, cols: Int, cells: List[(Int, Int)]) -> List[(Int, Int)] {
  let inside = |r: Int, c: Int| r >= 0 && r < rows && c >= 0 && c < cols;
  // Union-find over cell index r * cols + c; union by size keeps trees shallow.
  let mut parent: Map[Int, Int] = map_new();
  let mut size: Map[Int, Int] = map_new();
  let mut islands = 0;
  let mut largest = 0;
  let mut out: List[(Int, Int)] = [];
  for (r, c) in cells {
    let me = r * cols + c;
    if inside(r, c) && !map_contains(parent, me) {
      parent = map_set(parent, me, me);
      size = map_set(size, me, 1);
      islands = islands + 1;
      for (nr, nc) in [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)] {
        let nb = nr * cols + nc;
        if inside(nr, nc) && map_contains(parent, nb) {
          let a = find_root(parent, me);
          let b = find_root(parent, nb);
          if a != b {
            let big = if size[a] < size[b] { b } else { a };
            let small = if big == a { b } else { a };
            parent = map_set(parent, small, big);
            size = map_set(size, big, size[big] + size[small]);
            islands = islands - 1;
          }
        }
      }
      largest = max(largest, size[find_root(parent, me)]);
    }
    out = push(out, (islands, largest));
  }
  out
}

fn find_root(parent: Map[Int, Int], x: Int) -> Int {
  let mut r = x;
  while parent[r] != r {
    r = parent[r];
  }
  r
}
